<!doctype html><html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout — Nodexa</title><style>*{box-sizing:border-box}body{margin:0;background:#07111f;color:#eef5ff;font-family:Inter,Arial,sans-serif}.wrap{max-width:980px;margin:auto;padding:50px 20px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:30px}.card{background:#0c192b;border:1px solid #1d3655;border-radius:18px;padding:26px}.grid{display:grid;grid-template-columns:1.4fr .8fr;gap:20px}.line{display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px solid #19314d}.muted{color:#91a7c4}.total{font-size:28px;font-weight:900}.pay{width:100%;padding:15px;border:0;border-radius:11px;background:#6d4aff;color:white;font-weight:800;opacity:.55}.notice{padding:14px;border-radius:10px;background:#132844;color:#b9d5ff;margin-top:16px}a{color:#8d7aff}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><div class="top"><b style="font-size:24px">Nodexa Checkout</b><a href="{{route('store.index')}}">Fortsæt shopping</a></div><div class="grid"><section class="card"><div class="muted">Ordre #{{$order->id}}</div><h1>{{$order->product->name}}</h1><div class="line"><span>Servernavn</span><b>{{$order->server_name}}</b></div><div class="line"><span>RAM</span><b>{{$order->product->memory}} MB</b></div><div class="line"><span>Disk</span><b>{{$order->product->disk}} MB</b></div><div class="line"><span>CPU</span><b>{{$order->product->cpu}}%</b></div><div class="line"><span>Backups</span><b>{{$order->product->backups}}</b></div></section><aside class="card"><div class="muted">Betales månedligt</div><p class="total">{{number_format($order->amount,2,',','.')}} DKK</p><button class="pay" disabled>Betaling tilkobles i næste trin</button><div class="notice">Ordren er gemt som <b>afventer betaling</b>. Serveren provisioneres først efter bekræftet betaling.</div><p><a href="{{route('store.orders')}}">Se mine ordrer →</a></p></aside></div></main></body></html>